import React from 'react';
import { Container, Button, Alert } from 'react-bootstrap';
import { Link } from 'react-router-dom';

const NotFoundPage = () => {
  return (
    <Container className="py-5 text-center">
      <div className="mb-4">
        <i className="fas fa-exclamation-triangle fa-4x text-warning mb-3"></i>
        <h1 className="display-4 fw-bold">404</h1>
        <h2 className="h3 mb-3">Halaman Tidak Ditemukan</h2>
        <p className="lead text-muted mb-4">
          Halaman yang Anda cari tidak ditemukan atau telah dipindahkan.
        </p>
      </div>

      <Alert variant="light" className="mb-4 mx-auto" style={{ maxWidth: '600px' }}>
        <Alert.Heading>Mungkin Anda ingin:</Alert.Heading>
        <ul className="text-start mb-0">
          <li>Kembali ke halaman sebelumnya</li>
          <li>Pergi ke halaman utama</li>
          <li>Melakukan pencarian vendor atau paket</li>
        </ul>
      </Alert>

      <div className="d-flex justify-content-center gap-3 flex-wrap">
        <Button as={Link} to="/" variant="primary" size="lg">
          <i className="fas fa-home me-2"></i>Beranda
        </Button>
        <Button as={Link} to="/vendor" variant="success" size="lg">
          <i className="fas fa-building me-2"></i>Cari Vendor
        </Button>
        <Button as={Link} to="/package" variant="info" size="lg">
          <i className="fas fa-box me-2"></i>Cari Paket
        </Button>
        <Button variant="outline-secondary" size="lg" onClick={() => window.history.back()}>
          <i className="fas fa-arrow-left me-2"></i>Kembali
        </Button>
      </div>

      <div className="mt-5 pt-4 border-top">
        <p className="text-muted small">
          SPSE Scraper v9.0 • © 2026 • Support tahun 2023-2026
        </p>
      </div>
    </Container>
  );
};

export default NotFoundPage;